from common import *
import subprocess

def run(name,argv):
    log=TMP/f'{name}.log'
    with log.open('w') as f:r=subprocess.run([sys.executable,'-u',*map(str,argv)],stdout=f,stderr=subprocess.STDOUT,cwd=ROOT)
    if r.returncode:raise RuntimeError(f'{name} failed; inspect {log}')

if __name__=='__main__':
    register_adapter(__file__)
    while not (BASE/'docs'/f'{PREFIX}-original-comparison.json').exists():
        s=read(STATE)
        if any(j['status']=='failed' for j in s['jobs']):raise RuntimeError('initial fit failure')
        if time.time()>s['deadline']:raise RuntimeError('deadline')
        time.sleep(10)
    comparison=read(BASE/'docs'/f'{PREFIX}-original-comparison.json')
    stable=all(c['objective_shared']['exact'] and c['valid_prediction']['exact'] and not c['changed_tree_rounds'] for c in comparison['comparisons'][:2])
    if not stable:raise RuntimeError('within-input repetition differs: inspect before recovery; deterministic diagnostic branch available')
    decision={'decision':'recover remaining old-label seeds','criterion':'Both seed3000 input treatments repeated exactly (all objectives/tree hashes/validation predictions); old selected49 and matched prior best objective. Recover original five-seed recipe to test whether the previously observed whole-account gap reproduces.', 'source':fingerprint(BASE/'docs'/f'{PREFIX}-original-comparison.json'),'chosen_repeat':1,'additional_fits':4,'prior_fits':103,'created_at':time.time()}
    write(BASE/'docs'/f'{PREFIX}-recovery-decision.json',decision)
    run('routes-new-archived',[TMP/'routes.py','new-s3000-r1-original','archived-new'])
    run('routes-old-new',[TMP/'routes.py','old-s3000-r1-original','new-s3000-r1-original'])
    s=read(STATE);s['phase']='recover_old_ensemble';write(STATE,s)
    for seed in [42,1000,2000,4000]:run(f'old-s{seed}-r1',[TMP/'fit.py','old',seed,1])
    s=read(STATE);s['phase']='inference';write(STATE,s)
    for year in range(2020,2027):run(f'inference-{year}',[TMP/'infer.py',year])
    run('inference-consolidate',[TMP/'infer.py','consolidate'])
    run('old-model-evaluation',[TMP/'evaluate_old.py'])
    s=read(STATE);s['phase']='recovered_ensemble_ready';write(STATE,s)
    print('Old five-seed recovery and formal model evaluation complete.',flush=True)
